import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
const contracts=readFileSync(new URL('../contracts/ThreeShapeV29.sol',import.meta.url),'utf8');
const factory=readFileSync(new URL('../contracts/ThreeShapeDeploymentV29.sol',import.meta.url),'utf8');
test('on-chain JSON metadata carries emoji, name and typed traits',()=>{
  assert.match(contracts,/function tokenURI\(/);
  assert.match(contracts,/data:application\/json;base64,/);
  assert.match(contracts,/Green Apple/);
  assert.match(contracts,/Star/);
  assert.match(contracts,/trait_type":"fruit/);
  assert.match(contracts,/🍏/);
  assert.match(contracts,/🌟/);
  assert.doesNotMatch(contracts,/image\/svg\+xml|ipfs:\/\//);
});
test('deployment predicts five CREATE contract addresses',()=>{
  assert.match(factory,/bytes1\(0xd6\),bytes1\(0x94\),address\(this\),bytes1\(nonce\)/);
  assert.match(factory,/type\(ThreeShapeTokenV29\)\.creationCode/);
  assert.match(factory,/type\(ThreeShapeNFTV29\)\.creationCode/);
  assert.match(factory,/type\(ThreeShapeReserveV29\)\.creationCode/);
  assert.match(factory,/type\(ThreeShapeGameV29\)\.creationCode/);
  assert.match(factory,/type\(ThreeShapeLiquidityV29\)\.creationCode/);
  assert.match(factory,/address mismatch/);
});
test('LP budget expires at sale even if pool add fails',()=>{
  assert.match(contracts,/lpBudgetExpired\+=batchBudget/);
  assert.match(contracts,/catch \{emit LPAttemptFailed\(\);\}/);
  assert.match(contracts,/require\(msg.sender==address\(game\)/);
});
test('star sales are independent from game shares',()=>{
  const buy=contracts.split('function buyStars(')[1];
  assert.ok(buy);
  assert.doesNotMatch(buy,/require\(!ended\(/);
});

test('initial pool uses fixed 8 USDT per 14.3m 3SHAPE, independent of accumulated reserve',()=>{
  assert.match(contracts,/funds=maxMint\*8\*unit\/\(14_300_000 ether\)/);
  assert.match(contracts,/require\(available>=funds&&funds>0/);
});
test('NFT metadata name includes human-readable fruit name',()=>{
  assert.match(contracts,/Three Shape ',names\[k-1\]/);
});

test('Solidity UTF-8 emoji literals use unicode prefix',()=>{
  assert.match(contracts,/unicode"🍏"/);
  assert.match(contracts,/unicode"🌟"/);
  assert.doesNotMatch(contracts,/symbols=\["🍏"/);
});

test('reward calculation uses valid Solidity ether denomination',()=>{
  assert.match(contracts,/top\[stage-1\]\*\(1 ether\)/);
  assert.doesNotMatch(contracts,/\*ether\b/);
});

import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import ganache from 'ganache';
import {ethers} from 'ethers';
const output=JSON.parse(fs.readFileSync('artifacts/compiler-output.json','utf8'));
const source='contracts/ThreeShapeV29.sol';
const artifact=(file,name)=>output.contracts[file][name];
const UNIT=10n**18n;
async function fixture(accounts=12){
 const engine=ganache.provider({logging:{quiet:true},wallet:{totalAccounts:accounts},miner:{blockGasLimit:60000000}});
 const provider=new ethers.BrowserProvider(engine,'any',{cacheTimeout:-1});provider.pollingInterval=10;
 const signer=await provider.getSigner(),address=await signer.getAddress();
 async function deploy(file,name,args=[]){const a=artifact(file,name);const c=await new ethers.ContractFactory(a.abi,'0x'+a.evm.bytecode.object,signer).deploy(...args);await c.waitForDeployment();return c;}
 const mock='contracts/test/MocksV29.sol';
 const usdt=await deploy(mock,'MockUSDT'),registry=await deploy(mock,'MockRegistry');
 const factory=await deploy('contracts/ThreeShapeDeploymentV29.sol','ThreeShapeDeploymentV29');
 const pair=await deploy(mock,'MockPair',[await factory.predicted(1),await usdt.getAddress()]);
 const amm=await deploy(mock,'MockFactory',[await pair.getAddress()]);
 const router=await deploy(mock,'MockRouter',[await amm.getAddress(),await pair.getAddress()]);
 await assert.rejects(factory.connect(await provider.getSigner(1)).deploy.staticCall(await usdt.getAddress(),await registry.getAddress(),address,await router.getAddress(),await pair.getAddress()),/deployer only/);
 await(await factory.deploy(await usdt.getAddress(),await registry.getAddress(),address,await router.getAddress(),await pair.getAddress(),{gasLimit:15000000})).wait();
